parameters.jsCode:
// Controla lo que devolvió el agente ANTES de mandarlo por WhatsApp
const msg = $('Preparar mensaje').first().json;
const ses = $('Contexto de sesión').first().json;
const salida = String($json.output ?? '');
const pasos = $json.intermediateSteps ?? [];

let r = null;
// Algunos modelos escriben su razonamiento entre <think> y </think> antes del JSON: se descarta
const limpio = salida.replace(/<think>[\s\S]*?<\/think>/g, '').replace(/```json|```/g, '').trim();
try { r = JSON.parse(limpio.slice(limpio.indexOf('{'), limpio.lastIndexOf('}') + 1)); } catch (e) { r = null; }

const acciones = ['pedir_identificacion', 'informar', 'informar_politica', 'ofrecer_reclamo', 'reclamo_creado', 'cerrar', 'derivar', 'fuera_de_alcance', 'cerrar_sesion'];
const RESPALDO = 'En este momento no es posible procesar su consulta. Un analista se comunicará con usted por correo electrónico.';

// Lo que hizo de verdad el agente se toma de los pasos, no de lo que dice
const obs = p => { try { return typeof p.observation === 'string' ? JSON.parse(p.observation) : p.observation; } catch (e) { return {}; } };
const herramientas = [...new Set(pasos.map(p => p.action?.tool).filter(Boolean))];
// La herramienta devuelve una lista con un objeto: se toma el primero
const reclamo = pasos.map(obs).map(o => (Array.isArray(o) ? o[0] : o)).map(o => o?.resultado ?? o).find(o => o?.id_reclamo);

// RAG: qué devolvió de verdad buscar_politicas (el Vector Store). Cada fragmento llega como {type:'text', text:'{"pageContent":...,"metadata":...}'}
const pasosRag = pasos.filter(p => p.action?.tool === 'buscar_politicas');
const fragmentos = [];
let falloRag = false;
for (const p of pasosRag) {
  let o = p.observation;
  try { if (typeof o === 'string') o = JSON.parse(o); } catch (e) { o = null; }
  if (!Array.isArray(o)) { falloRag = true; continue; }   // un error del store o de los embeddings llega como texto, no como lista
  for (const d of o) {
    try { const j = typeof d?.text === 'string' ? JSON.parse(d.text) : d; if (j?.pageContent) fragmentos.push(j); } catch (e) { /* fragmento ilegible: se ignora */ }
  }
}
const contexto = fragmentos.map(f => f.pageContent).join('\n');
const temas = [...new Set(fragmentos.map(f => f.metadata?.tema).filter(Boolean))];
// Números "sueltos" de un texto, sin separador de miles: sirve para comparar lo que dijo la IA con lo que estaba escrito
const nums = t => new Set((String(t).replace(/(\d)\.(?=\d{3}\b)/g, '$1').match(/\d+/g) ?? []).map(Number));
const obsTexto = p => typeof p.observation === 'string' ? p.observation : JSON.stringify(p.observation ?? '');
const numsContexto = nums(contexto);
const numsFuente = nums([contexto, msg.texto_para_ia, ...pasos.map(obsTexto)].join(' '));

// Si una herramienta falló (por ejemplo, el workflow de herramientas está apagado o el Vector Store no responde),
// la IA podría seguir la charla como si nada: se detecta acá y se responde con el mensaje de respaldo
const falloHerramienta = falloRag || pasos.some(p => p.action?.tool !== 'buscar_politicas' && /There was an error|"error"\s*:/i.test(obsTexto(p)));

let respuesta = r && typeof r.respuesta === 'string' ? r.respuesta.trim() : '';
let accion = r && acciones.includes(r.accion) ? r.accion : 'derivar';
let control_respuesta = 'ok';

if (!respuesta) { respuesta = RESPALDO; control_respuesta = 'reemplazada: respuesta vacía o con formato inválido'; }
else if (falloHerramienta) { respuesta = RESPALDO; accion = 'derivar'; control_respuesta = falloRag ? 'reemplazada: la base de políticas no respondió' : 'reemplazada: falló una herramienta'; }
// 1. No puede filtrarse la clave, un CUIT ajeno ni códigos internos
else if ((msg.clave && respuesta.includes(msg.clave)) || /\bT-\d{2}\b|TMS-\d|\bF-\d{4}\b|\b\d{2}-?\d{8}-?\d\b/.test(respuesta)) {
  respuesta = RESPALDO; control_respuesta = 'reemplazada: datos internos o sensibles en la respuesta';
}
// 2. No puede decir que abrió un reclamo si la herramienta no lo creó
else if (accion === 'reclamo_creado' && !reclamo) {
  respuesta = RESPALDO; control_respuesta = 'reemplazada: dijo reclamo sin crearlo';
}
// 3. Políticas: solo se responde con lo recuperado del Vector Store (grounding)
else if (accion === 'informar_politica' && pasosRag.length === 0) {
  respuesta = RESPALDO; accion = 'derivar'; control_respuesta = 'reemplazada: respondió una política sin consultar la base';
}
// El agente habló de un tema de políticas sin usar ninguna herramienta (respondió de memoria, pasó en la prueba del 15/11)
else if (pasos.length === 0 && /adelant|pagos? prioritarios?|retenci|\bcbu\b|cuenta bancaria|tarifa|requisito|nota de cr[eé]dito|certificado/i.test(respuesta)
         && /\b(debe|deber[aá]|hay que|tiene que|se (pide|solicita|env[ií]a|presenta)|puede (solicitar|pedir))\b/i.test(respuesta)) {
  respuesta = RESPALDO; accion = 'derivar'; control_respuesta = 'reemplazada: habló de políticas sin consultar la base';
}
// Prometió una acción que no hizo ("procederé a abrir el reclamo"): o la herramienta lo crea en este turno, o no se dice
else if (!reclamo && /proceder[eé] a (abrir|registrar)|voy a (abrir|registrar)|abrir[eé] (el|un|su) (reclamo|solicitud)|registrar[eé] (el|un|su) (reclamo|solicitud)/i.test(respuesta)) {
  respuesta = RESPALDO; accion = 'derivar'; control_respuesta = 'reemplazada: prometió abrir un reclamo sin crearlo';
}
else if (accion === 'informar_politica' && fragmentos.length === 0) {
  respuesta = RESPALDO; accion = 'derivar'; control_respuesta = 'reemplazada: la búsqueda no devolvió fragmentos';
}
else if (accion === 'informar_politica' && [...nums(respuesta)].some(n => !numsFuente.has(n))) {
  const extra = [...nums(respuesta)].filter(n => !numsFuente.has(n));
  respuesta = RESPALDO; accion = 'derivar'; control_respuesta = 'reemplazada: números que no están en los fragmentos (' + extra.join(', ') + ')';
}
else if (accion === 'informar_politica' && (respuesta.toLowerCase().match(/[\w.+-]+@[\w-]+\.[\w.]+/g) ?? []).some(m => !contexto.toLowerCase().includes(m.replace(/\.$/, '')))) {
  respuesta = RESPALDO; accion = 'derivar'; control_respuesta = 'reemplazada: correo que no está en los fragmentos';
}
// 4. No puede prometer plazos que nadie definió ("en 48 horas hábiles"): pasó en el ensayo del 7/11.
//    Un plazo solo se acepta si ese número está escrito en un fragmento recuperado.
else if ([...respuesta.matchAll(/\b(\d+)\s*(horas|hs\.?|d[ií]as)\b/gi)].some(m => !numsContexto.has(Number(m[1])))) {
  respuesta = reclamo ? `Registramos su reclamo ${reclamo.id_reclamo}. Un analista lo va a revisar y le vamos a responder por correo electrónico. Quedamos a su disposición.` : RESPALDO;
  control_respuesta = 'reemplazada: prometió un plazo que no viene de una herramienta';
}
// 5. WhatsApp: corto
else if (respuesta.length > 700) { respuesta = respuesta.slice(0, 680).replace(/\s\S*$/, '') + '…'; control_respuesta = 'recortada'; }

// 6. Los tipos de reclamo son códigos internos ("de tipo derivar a persona", pasó en la prueba del 15/11):
//    no se descarta la respuesta, solo se quita el nombre del tipo
const TIPOS = /\s*\b(?:del?\s+)?tipo\s+["“']?(?:derivar[ _]a[ _](?:una[ _])?persona|generaci[oó]n[ _](?:de[ _])?clave|factura[ _]no[ _]recibida|fuera[ _]de[ _]t[eé]rmino|disconformidad)["”']?/gi;
const sinTipos = respuesta.replace(TIPOS, '').replace(/\bderivar_a_persona\b/gi, 'una consulta con un representante');
if (sinTipos !== respuesta) {
  respuesta = sinTipos;
  if (control_respuesta === 'ok') control_respuesta = 'ajustada: se quitó el nombre interno del tipo de reclamo';
}

// Avisos de sesión: los escribe el flujo, no la IA, para que salgan siempre igual
const cierra_sesion = accion === 'cerrar_sesion' && !!ses.id_transportista;
if (cierra_sesion) respuesta += '\n\nSu sesión ha finalizado. Para realizar una nueva consulta deberá identificarse nuevamente con su CUIT y clave.';
if (ses.sesion_vencida) respuesta = 'Su sesión anterior finalizó por inactividad (30 minutos).\n\n' + respuesta;

return [{
  json: {
    respuesta, accion, comprobante: r?.comprobante ?? '',
    // Campos que agrega este nodo (no los genera la IA):
    telefono: msg.telefono,
    message_id: msg.message_id,
    id_transportista: ses.id_transportista || '',
    herramientas_usadas: herramientas.map(h => h === 'buscar_politicas' ? `buscar_politicas (${fragmentos.length} fragmentos${temas.length ? ': ' + temas.join(', ') : ''})` : h).join(', '),
    fragmentos_recuperados: fragmentos.length,
    id_reclamo: reclamo?.id_reclamo ?? '',
    control_respuesta,
    cierra_sesion,
    avisar_analista: control_respuesta.startsWith('reemplazada'),
    mensaje_original: msg.texto_para_ia,
  },
}];

